_EFFECTS_CATALOG: List[CatalogItemResponse] = []
_FILTERS_CATALOG: List[CatalogItemResponse] = []
_TRANSITIONS_CATALOG: List[CatalogItemResponse] = []


def _parse_plan(plan_str: str) -> PlanType:
    if plan_str == "PRO":
        return PlanType.PRO
    if plan_str == "PREMIUM":
        return PlanType.PREMIUM
    return PlanType.FREE


def get_effects_catalog() -> List[CatalogItemResponse]:
    """Returns the production list of effects imported from asset_catalog.xlsx."""
    global _EFFECTS_CATALOG
    if not _EFFECTS_CATALOG:
        _EFFECTS_CATALOG = [
            CatalogItemResponse(
                id=item["id"],
                name=item["name"],
                type=AssetType.EFFECT,
                category=item["category"],
                thumbnail=item["thumbnail"],
                required_plan=_parse_plan(item["required_plan"]),
                engine_key=item["engine_key"],
                enabled=item["enabled"],
                version=item["version"],
                user_has_access=True,
                metadata=item["metadata"],
            )
            for item in _EFFECTS_RAW
        ]
    return _EFFECTS_CATALOG


